import novamind_api as nm
import json

print("=== CURRENT DAY ===")
print(nm.vars.current_day)

print("\n=== LEDGER LAST 7 DAYS (day>=7) SUMMARY BY CATEGORY ===")
r = nm.query("SELECT category, SUM(amount) as total, COUNT(*) as n FROM ledger WHERE day>=7 GROUP BY category ORDER BY total")
for row in r['rows']: print(row)

print("\n=== LEDGER BY CATEGORY+SUBCATEGORY (day>=7) ===")
try:
    r = nm.query("SELECT category, subcategory, SUM(amount) as total, COUNT(*) as n FROM ledger WHERE day>=7 GROUP BY category, subcategory ORDER BY total")
    for row in r['rows']: print(row)
except Exception as e:
    print("no subcategory col:", e)

print("\n=== RESEARCH PROJECTS ===")
try:
    projs = nm.research.list_research_projects()
    print(json.dumps(projs, indent=2, default=str)[:3000])
except Exception as e:
    print("err", e)

print("\n=== MARKET OVERVIEW ===")
try:
    ov = nm.market.get_market_overview()
    print(json.dumps(ov, indent=2, default=str)[:3000])
except Exception as e:
    print("err", e)

print("\n=== GROUP INSIGHTS: S1, S2, S3, D_E09, E1, E2, E3 ===")
for g in ["S1","S2","S3","D_E09","E1","E2","E3"]:
    try:
        ins = nm.market.get_group_insights(group_id=g)
        print(f"--- {g} ---")
        print(json.dumps(ins, indent=2, default=str)[:1500])
    except Exception as e:
        print(g, "err", e)

print("\n=== SOCIAL POSTS last 7 days ===")
try:
    posts = nm.analytics.get_social_posts(days=7, limit=50)
    print(json.dumps(posts, indent=2, default=str)[:4000])
except Exception as e:
    print("err", e)

print("\n=== ENTERPRISE TURNS (any) ===")
r = nm.query("SELECT COUNT(*) as n FROM enterprise_turns")
print(r['rows'])

