import json
from collections import defaultdict

h126 = None
try:
    h126 = json.load(open('tenure_histogram_day126.json'))
except Exception as e:
    print("no day126 file:", e)

h133 = json.load(open('tenure_histogram_day133.json'))

if h126:
    for g in ['S1','S2','S3']:
        d126 = {int(k):v for k,v in h126[g].items()}
        d133 = {int(k):v for k,v in h133[g].items()}
        print(f"\n=== {g} (day126->133) ===")
        bucket_before = defaultdict(float)
        bucket_after = defaultdict(float)
        nb_before=nb_after=0.0
        for T, n in d126.items():
            T2 = T + 7
            n2 = d133.get(T2, 0)
            boundary = None
            for mult in range(30, 400, 30):
                if T < mult <= T2:
                    boundary = mult
                    break
            if boundary is not None:
                k = boundary // 30
                bucket_before[k] += n
                bucket_after[k] += n2
            else:
                nb_before += n; nb_after += n2
        for k in sorted(bucket_before):
            b, a = bucket_before[k], bucket_after[k]
            churn = 1 - a/b if b>0 else float('nan')
            print(f"  eval#{k} (~{k*30}d): before={b:.0f} after={a:.0f} marginal_churn={churn:.3f}")
        if nb_before>0:
            print(f"  no-boundary: before={nb_before:.0f} after={nb_after:.0f} survival={nb_after/nb_before:.3f}")
EOF
