import json

old = json.load(open('tenure_histogram_day147.json'))
new = json.load(open('tenure_histogram_day154.json'))

print("=== MARGINAL CHURN AT EVAL BOUNDARIES (day147 -> day154, +7d) ===")
for g in ['S1','S2','S3']:
    o = {int(k):v for k,v in old[g].items()}
    n = {int(k):v for k,v in new[g].items()}
    print(f"--- {g} ---")
    by_eval = {}
    for t, cnt_before in sorted(o.items()):
        t_after = t + 7
        if t_after in n:
            cnt_after = n[t_after]
            # does a 30-day boundary fall in (t, t+7]?
            boundary = None
            for b in range(30, 400, 30):
                if t < b <= t_after:
                    boundary = b
                    break
            survival = cnt_after / cnt_before if cnt_before > 0 else None
            marker = f"BOUNDARY@{boundary}(eval#{boundary//30})" if boundary else "no-boundary"
            if boundary or cnt_before >= 5:
                print(f"  t={t:>4} -> t+7={t_after:>4}: before={cnt_before:>4} after={cnt_after:>4} survival={survival:.3f}  {marker}")
            if boundary:
                by_eval.setdefault(boundary//30, []).append((cnt_before, cnt_after))
    print(f"  --- {g} SUMMARY BY EVAL# ---")
    for ev, pairs in sorted(by_eval.items()):
        tb = sum(p[0] for p in pairs)
        ta = sum(p[1] for p in pairs)
        print(f"    eval#{ev}: n_before={tb} n_after={ta} churn_rate={1-ta/tb:.3f}" if tb else "")
EOF
./novamind-operation python churn_diff_154.py

