cd ~/novamind 2>/dev/null; cat > next_week_load_161.py << 'EOF'
import json
hist = json.load(open('tenure_histogram_day161.json'))
hist = {g: {int(k): v for k, v in d.items()} for g, d in hist.items()}

# Simulate forward assuming NO further churn (pure aging) to see boundary-crossing cohort sizes
# for the next 12 weeks -- this reveals the deterministic "revenue rhythm" from lumpy signup history.
cur = {g: dict(d) for g, d in hist.items()}
for wk in range(1, 13):
    loads = {}
    new_cur = {g: {} for g in cur}
    for g, d in cur.items():
        for tenure, count in d.items():
            t_after = tenure + 7
            boundary = None
            for b in range(30, 450, 30):
                if tenure < b <= t_after:
                    boundary = b
                    break
            if boundary:
                loads.setdefault(g, {}).setdefault(boundary, 0)
                loads[g][boundary] += count
            new_cur[g][t_after] = new_cur[g].get(t_after, 0) + count  # no churn applied (pure aging for load-forecast purposes)
    cur = new_cur
    total_n = sum(sum(b.values()) for b in loads.values())
    print(f"week+{wk}: total_crossing={total_n}  detail={ {g: b for g,b in loads.items()} }")
EOF
./novamind-operation python next_week_load_161.py

