import random, statistics, json
exec(open('forecast_model_v38.py').read().split(\"if __name__\")[0])

# Sensitivity: force churn_adj fixed at pessimistic levels, no reopen scenario, to isolate tier-revert risk
def simulate_fixed_adj(adj, n_draws=1500, seed=99):
    random.seed(seed)
    results = {h: [] for h in [1,4,12,26]}
    for draw in range(n_draws):
        drawn_mean_base = {}
        for g in CHURN_MEAN_BASE:
            drawn_mean_base[g] = {}
            for e, mu in CHURN_MEAN_BASE[g].items():
                sd_s = CHURN_SD_STRUCTURAL[g][e]
                drawn_mean_base[g][e] = min(max(random.gauss(mu+adj, sd_s), 0.03), 0.97)
        pop = dict(POP0); cash = CASH0
        for wk in range(1,27):
            subs_prev = sum(pop.values())
            ops_now = max(150.0, OPS_BASE_NOW*(subs_prev/BASE_SUBS0)**0.5)
            if cash < 10000: ops_now = max(OPS_FLOOR, ops_now*0.7)
            if cash < 4000: ops_now = min(ops_now, OPS_FLOOR)
            drift = CHURN_DRIFT_PER_WEEK*wk
            drawn_mean = {g:{e:min(0.97,v+drift) for e,v in drawn_mean_base[g].items()} for g in drawn_mean_base}
            revenue=0.0; new_pop={}
            for (g,tenure,plan,price),count in pop.items():
                if count<=0: continue
                t_after=tenure+7; boundary=None
                for b in range(30,480,30):
                    if tenure<b<=t_after: boundary=b; break
                if boundary:
                    ev=eval_index(boundary); mu=drawn_mean[g][ev]; sd_w=CHURN_SD_WEEKLY[g][ev]
                    cr=min(max(random.gauss(mu,sd_w),0.02),0.98)
                    survivors=count*(1-cr); revenue+=survivors*price
                    new_pop[(g,t_after,plan,price)]=new_pop.get((g,t_after,plan,price),0)+survivors
                else:
                    new_pop[(g,t_after,plan,price)]=new_pop.get((g,t_after,plan,price),0)+count
            pop=new_pop
            subs_now=sum(pop.values())
            usage_week=USAGE_PER_SUB_WEEK*subs_now
            usage_A=usage_week*USAGE_A_FRAC; usage_C=usage_week*USAGE_C_FRAC
            compute_wk=usage_A*RATE_A_T1+usage_C*RATE_C_T3
            peak_day=(usage_week/7)*PEAK_TO_AVG_RATIO
            capacity_wk=capacity_cost_for_peak(peak_day)*7
            ops_wk=ops_now*7; lead_wk=LEADS_PER_WEEK_BASE*(subs_now/BASE_SUBS0)*LEAD_COST
            costs=capacity_wk+compute_wk+ops_wk+lead_wk
            cash+=revenue-costs
            if wk in results: results[wk].append(cash)
    return results

for adj in [0.0, 0.06, 0.12, 0.20]:
    res = simulate_fixed_adj(adj)
    line = f'adj={adj:.2f}: '
    for h in [1,4,12,26]:
        vals=sorted(res[h]); n=len(vals)
        line += f'wk{h}=\${vals[n//2]:,.0f} '
    print(line)
