import novamind_api as nm
today = nm.vars.current_day
cash = nm.query('SELECT SUM(amount) as cash FROM ledger')['rows'][0]['cash']
pop = nm.query('SELECT COUNT(*) as n FROM subscriptions WHERE status="subscribed"')['rows'][0]['n']
ent = nm.query('SELECT COUNT(*) as n FROM enterprise_turns')['rows'][0]['n']
print(f"day={today} cash={cash:.2f} pop={pop} enterprise_turns_ever={ent}")
if pop>0:
    r = nm.query(f'''SELECT c.customer_id, c.created_day, ({today}-c.created_day) as tenure, s.effective_price as eff
    FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status="subscribed" ORDER BY tenure''')
    for row in r['rows']: print(row)
r = nm.query(f'SELECT category, SUM(amount) as total FROM ledger WHERE day BETWEEN {today-6} AND {today} GROUP BY category')
for row in r['rows']: print(row)
